<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driven;

use Override;
use Throwable;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Exception\BadRequestException;
use Civi\Lughauth\Shared\Security\PasswordHasher;
use Civi\Lughauth\Shared\Security\ReversibleSecretStorage;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserCommandRepositoryGateway;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\Gateway\UserMfaRecoveryCodeFilter;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\Gateway\UserMfaRecoveryCodeCommandRepositoryGateway;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\UserMfaRecoveryCode;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\UserMfaRecoveryCodeAttributes;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\UserMfaRecoveryCodeCodeHashVO;
use Civi\Lughauth\Features\OAuth\Common\Infrastructure\Driven\UserLoaderAdapter;
use Civi\Lughauth\Features\OAuth\Mfa\Domain\Gateway\UserMfaGateway;
use Civi\Lughauth\Features\OAuth\Profile\Domain\Gateway\MfaGateway;
use Civi\Lughauth\Features\OAuth\Profile\Domain\MfaSetup;

/**
 * Infrastructure adapter that implements MfaGateway by delegating to the shared MFA subsystem.
 *
 * This class bridges the Profile feature's domain MfaGateway port to the concrete
 * UserMfaGateway and UserCommandRepositoryGateway dependencies that live in the Access and OAuth/Mfa
 * bounded contexts.  It is responsible for resolving the tenant and user entities via
 * UserLoaderAdapter before forwarding any TOTP operation to the underlying gateway.
 *
 * Distributed tracing spans and structured log entries are emitted for every public
 * operation using the LoggerAwareTrait and TracerAwareTrait mixins, ensuring observability
 * without coupling the domain layer to any particular tracing library.
 *
 * When enabling MFA the adapter validates the user-supplied OTP against the provisional
 * seed and throws BadRequestException for an invalid code, preventing storage of an
 * unverified seed.
 */
class MfaAdapter implements MfaGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    private const int RECOVERY_CODE_COUNT = 10;

    public function __construct(
        private readonly UserLoaderAdapter $users,
        private readonly UserCommandRepositoryGateway $repository,
        private readonly UserMfaGateway $mfaGateway,
        private readonly UserMfaRecoveryCodeCommandRepositoryGateway $recoveryWrite,
        private readonly ReversibleSecretStorage $secrets,
        private readonly PasswordHasher $hasher,
    ) {
    }

    /**
     * Checks whether TOTP second-factor authentication is currently active for the user.
     *
     * Resolves the tenant and user, then reads the isUseSecondFactors flag stored on
     * the user entity; returns true only when the flag is explicitly set to true.
     */
    #[Override]
    public function isEnabled(string $userUid, string $tenant): bool
    {
        $theTenant = $this->users->checkTenant($tenant, $userUid);
        $theUser = $this->users->checkUserSubjet($theTenant, $userUid);
        return (bool) $theUser->isUseSecondFactors();
    }

    /**
     * Generates a fresh TOTP seed and a QR code image for the MFA enrolment wizard.
     *
     * Delegates to UserMfaGateway::configurationForNewMfa() and wraps the result in
     * a MfaSetup value object.  The seed is provisional until confirmed via enable().
     */
    #[Override]
    public function buildSetup(string $userUid, string $tenant): MfaSetup
    {
        $this->logDebug("Build MFA setup for user");
        $span = $this->startSpan("Build MFA setup for user");
        try {
            $theTenant = $this->users->checkTenant($tenant, $userUid);
            $theUser = $this->users->checkUserSubjet($theTenant, $userUid);
            $response = $this->mfaGateway->configurationForNewMfa($tenant, $theUser->getName());
            return new MfaSetup(seed: $response->seed, qrImage: $response->image);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Verifies the supplied OTP against the provisional seed and, if valid, stores the seed.
     *
     * Throws BadRequestException when the OTP is incorrect so the profile UI can render
     * an inline error without triggering a generic 500 response.
     */
    #[Override]
    public function enable(string $userUid, string $tenant, string $seed, string $otp): void
    {
        $this->logDebug("Enable MFA for user");
        $span = $this->startSpan("Enable MFA for user");
        try {
            $theTenant = $this->users->checkTenant($tenant, $userUid);
            $theUser = $this->users->checkUserSubjet($theTenant, $userUid);
            $valid = $this->mfaGateway->verifyNewOpt($tenant, $theUser->getName(), $seed, $otp);
            if (!$valid) {
                throw new BadRequestException('Invalid OTP code');
            }
            $this->mfaGateway->storeSeed($tenant, $theUser->getName(), $seed);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    /**
     * Clears the stored TOTP seed so the user is no longer challenged for a second factor.
     *
     * Persists the change through UserCommandRepositoryGateway::update() using the change-set returned
     * by User::setMfaSeed($secrets, null).
     */
    #[Override]
    public function disable(string $userUid, string $tenant): void
    {
        $this->logDebug("Disable MFA for user");
        $span = $this->startSpan("Disable MFA for user");
        try {
            $theTenant = $this->users->checkTenant($tenant, $userUid);
            $theUser = $this->users->checkUserSubjet($theTenant, $userUid);
            $changed = $theUser->setMfaSeed($this->secrets, null);
            $this->repository->update($theUser, $changed);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    #[Override]
    public function generateRecoveryCodes(string $userUid, string $tenant): array
    {
        $this->logDebug("Generate MFA recovery codes for user");
        $span = $this->startSpan("Generate MFA recovery codes for user");
        try {
            $userRef = new UserRef($userUid);
            $existing = $this->recoveryWrite->listForUpdate(
                (new UserMfaRecoveryCodeFilter())->withUser($userRef),
            );
            foreach ($existing->values() as $code) {
                $this->recoveryWrite->delete($code);
            }
            $plainCodes = [];
            for ($i = 0; $i < self::RECOVERY_CODE_COUNT; $i++) {
                $plain = strtoupper(bin2hex(random_bytes(5)));
                $attrs = (new UserMfaRecoveryCodeAttributes())
                    ->withDefaults()
                    ->user($userRef)
                    ->codeHash(UserMfaRecoveryCodeCodeHashVO::fromPlainText($this->hasher, $plain));
                $this->recoveryWrite->create(UserMfaRecoveryCode::create($attrs));
                $plainCodes[] = $plain;
            }
            return $plainCodes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    #[Override]
    public function countUnusedRecoveryCodes(string $userUid, string $tenant): int
    {
        $userRef = new UserRef($userUid);
        return $this->recoveryWrite->count(
            (new UserMfaRecoveryCodeFilter())->withUserUnused($userRef),
        );
    }
}
